      3, 1, 2, 1, 1, 2, 2, 1, 2, 0, 1, 2, 3, 1, 3, 1, &
      1, 3, 2, 1, 3, 0, 1, 3, 2, 0, 5, 0, 0, 5, 1, 0 /
   data cm_e(129:240) / &
      5, 2, 1, 4, 0, 1, 4, 1, 1, 4, 2, 2, 0, 0, 2, 0, &
      1, 2, 0, 2, 2, 1, 0, 2, 1, 1, 2, 1, 2, 2, 2, 0, &
      2, 2, 1, 2, 2, 2, 2, 3, 0, 2, 3, 1, 2, 3, 1, 0, &
      6, 0, 0, 6, 1, 1, 5, 0, 1, 5, 1, 2, 4, 0, 2, 4, &
      1, 3, 0, 0, 3, 0, 1, 3, 1, 0, 3, 1, 1, 3, 2, 0, &
      3, 2, 1, 3, 3, 0, 3, 3, 0, 0, 7, 0, 1, 6, 0, 2, &
      5, 0, 3, 4, 0, 4, 0, 0, 4, 1, 0, 4, 2, 0, 4, 3 /
contains
   ! (pd|dd)  L=7: 189 bra accumulators, 2199 ket accumulators (28863 terms), 648 components -- table driven
   subroutine rotaxis_pddd(nbra, ncb, bp, kab, nket, nck, kp, kcd, gc, cutoff, res, any)
      integer,  intent(in)  :: nbra, ncb, nket, nck
      real(dp), intent(in)  :: bp(5, nbra), kab(1*ncb, nbra)
      real(dp), intent(in)  :: kp(7, nket), kcd(1*nck, nket), gc(3), cutoff
      real(dp), intent(out) :: res(648, ncb*nck)
      logical,  intent(out) :: any
      real(dp) :: s(189, ncb), r(2199, ncb, nck), t(2199)
      real(dp) :: f(0:7), b(0:7), g(9), km(86), cm(80), zqp(0:7), v
      real(dp) :: p, ip, za, zb, eab, q, iq, yc, yd, ax, az, ecd
      real(dp) :: zq, alpha, tt, w, m2a, Rs, Rc, cy
      integer :: kq, bq, cc, ck, n, i, j, col

      Rs = gc(1); Rc = gc(2); cy = gc(3)
      any = .false.
      r = 0.0_dp
      do kq = 1, nket
         q = kp(1,kq); iq = kp(2,kq); yc = kp(3,kq); yd = kp(4,kq)
         ax = kp(5,kq); az = kp(6,kq); ecd = kp(7,kq)
         s = 0.0_dp
         do bq = 1, nbra
            eab = bp(5,bq)
            if (eab + ecd > cutoff) cycle
            any = .true.
            p = bp(1,bq); ip = bp(2,bq); za = bp(3,bq); zb = bp(4,bq)
            zq = za - az
            alpha = p*q/(p + q)
            tt = alpha*(ax*ax + cy*cy + zq*zq)
            call boys(f, tt, 7)
            w = 1.0_dp/sqrt(p + q)
            m2a = -2.0_dp*alpha
            do n = 0, 7
               b(n) = w*f(n)
               w = w*m2a
            end do
            zqp(0) = 1.0_dp
            do i = 1, 7
               zqp(i) = zqp(i-1)*zq
            end do
            do i = 1, 9
               g(i) = 1.0_dp
               do j = 1, g_e(3*i-2); g(i) = g(i)*ip; end do
               do j = 1, g_e(3*i-1); g(i) = g(i)*za; end do
               do j = 1, g_e(3*i); g(i) = g(i)*zb; end do
            end do
            do i = 1, 189
               v = g(s_g(i))*b(s_n(i))*zqp(s_k(i))
               do cc = 1, ncb
                  s(i,cc) = s(i,cc) + kab(cc,bq)*v
               end do
            end do
         end do
         if (.not. any) cycle
         do i = 1, 86
            km(i) = 1.0_dp
            do j = 1, km_e(4*i-3); km(i) = km(i)*iq; end do
            do j = 1, km_e(4*i-2); km(i) = km(i)*yc; end do
            do j = 1, km_e(4*i-1); km(i) = km(i)*yd; end do
            do j = 1, km_e(4*i); km(i) = km(i)*ax; end do
         end do
         do cc = 1, ncb
            t = 0.0_dp
            do i = 1, 28863
               t(rt_r(i)) = t(rt_r(i)) + real(rt_c(i), dp)/real(rt_d(i), dp)*km(rt_km(i))*s(rt_s(i),cc)
            end do
            do ck = 1, nck
               r(1:2199,cc,ck) = r(1:2199,cc,ck) + kcd(ck,kq)*t(1:2199)
            end do
         end do
      end do
      res = 0.0_dp
      if (.not. any) return
      do i = 1, 80
         cm(i) = 1.0_dp
         do j = 1, cm_e(3*i-2); cm(i) = cm(i)*Rs; end do
         do j = 1, cm_e(3*i-1); cm(i) = cm(i)*Rc; end do
         do j = 1, cm_e(3*i); cm(i) = cm(i)*cy; end do
      end do
      do ck = 1, nck
         do cc = 1, ncb
            col = cc + ncb*(ck-1)
            do i = 1, 5416
               res(at_comp(i),col) = res(at_comp(i),col) &
                  + real(at_c(i), dp)/real(at_d(i), dp)*cm(at_cm(i))*r(at_r(i),cc,ck)
            end do
         end do
      end do
   end subroutine rotaxis_pddd

end module rotaxis_pddd_m
